CREATE TABLE IF NOT EXISTS operations_monitor(id TEXT PRIMARY KEY,state_json TEXT NOT NULL,observed_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS operations_alerts(id TEXT PRIMARY KEY,kind TEXT NOT NULL,payload_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_at BIGINT NOT NULL DEFAULT 0,created_at BIGINT NOT NULL,delivered_at BIGINT NOT NULL DEFAULT 0);
